mapper.update:
UPDATE account_purge_jobs
SET status = 'DB_DONE',
    db_completed_at = #{dbCompletedAt}
WHERE id = #{id}

UPDATE account_purge_jobs
SET status = 'COMPLETED',
    db_completed_at = #{dbCompletedAt},
    completed_at = #{completedAt}
WHERE id = #{id}

mapper.select:
SELECT 
FROM account_purge_tasks
WHERE status = 'PENDING'
  AND task_type = #{taskType}

  AND provider = #{provider}

  AND (next_retry_at IS NULL OR next_retry_at <= #{currentTime})
ORDER BY next_retry_at, id
LIMIT #{limit}

mapper.update:
UPDATE account_purge_tasks
SET attempts = attempts + 1,
    last_attempt_at = #{currentTime},
    next_retry_at = #{leaseUntil}
WHERE id = #{id}
  AND status = 'PENDING'
  AND task_type = #{taskType}

  AND provider = #{provider}

  AND (next_retry_at IS NULL OR next_retry_at <= #{currentTime})

UPDATE account_purge_tasks
SET next_retry_at = #{nextRetryAt},
    last_error = #{lastError}
WHERE id = #{id}
  AND status = 'PENDING'

UPDATE account_purge_tasks
SET status = 'FAILED',
    next_retry_at = NULL,
    last_error = #{lastError}
WHERE id = #{id}
  AND status = 'PENDING'

UPDATE account_purge_jobs
SET status = 'COMPLETED',
    completed_at = #{completedAt}
WHERE id = #{purgeJobId}
  AND status = 'DB_DONE'
  AND NOT EXISTS (
      SELECT 1
      FROM account_purge_tasks t
      WHERE t.purge_job_id = #{purgeJobId}
        AND t.status <> 'COMPLETED'
  )
